            .strip_prefix("resend:")
            .or_else(|| lower.strip_prefix("rs "))
            .map(|r| r.trim().trim_start_matches('n'))
            .and_then(|r| r.split_whitespace().next())
            .and_then(|r| r.parse::<usize>().ok())
        {
            self.resend_from = Some(n);
        } else if lower.starts_with("ok") {
            self.waiting_ok = false;
        }
    }
}

